import { test, expect } from '@playwright/test';

test.describe('Table Row Selection Badge Count', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display correct badge count when multiple rows are selected', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Select first row using checkbox
    const firstCheckbox = page.getByRole('checkbox', { name: /row 1/i });
    await firstCheckbox.click();

    // Verify badge count shows 1
    const badge = page.getByRole('status', { name: /selected rows/i });
    await expect(badge).toContainText('1');

    // Select second row
    const secondCheckbox = page.getByRole('checkbox', { name: /row 2/i });
    await secondCheckbox.click();

    // Verify badge count updates to 2
    await expect(badge).toContainText('2');

    // Select third row
    const thirdCheckbox = page.getByRole('checkbox', { name: /row 3/i });
    await thirdCheckbox.click();

    // Verify badge count updates to 3
    await expect(badge).toContainText('3');

    // Verify selected rows are highlighted
    const firstRow = page.getByRole('row', { name: /row 1/i });
    const secondRow = page.getByRole('row', { name: /row 2/i });
    const thirdRow = page.getByRole('row', { name: /row 3/i });
    await expect(firstRow).toHaveClass(/selected/);
    await expect(secondRow).toHaveClass(/selected/);
    await expect(thirdRow).toHaveClass(/selected/);

    // Verify badge has correct styling
    await expect(badge).toHaveClass(/badge-active/);
  });

  test('should reset badge count when selection is cleared', async ({ page }) => {
    // Select first row
    const firstCheckbox = page.getByRole('checkbox', { name: /row 1/i });
    await firstCheckbox.click();

    // Verify badge count shows 1
    const badge = page.getByRole('status', { name: /selected rows/i });
    await expect(badge).toContainText('1');

    // Select second row
    const secondCheckbox = page.getByRole('checkbox', { name: /row 2/i });
    await secondCheckbox.click();

    // Verify badge count shows 2
    await expect(badge).toContainText('2');

    // Clear all selections using clear button
    const clearButton = page.getByRole('button', { name: /clear selection/i });
    await clearButton.click();

    // Verify badge count resets to 0
    await expect(badge).toContainText('0');

    // Verify no rows are highlighted
    const firstRow = page.getByRole('row', { name: /row 1/i });
    const secondRow = page.getByRole('row', { name: /row 2/i });
    const thirdRow = page.getByRole('row', { name: /row 3/i });
    await expect(firstRow).not.toHaveClass(/selected/);
    await expect(secondRow).not.toHaveClass(/selected/);
    await expect(thirdRow).not.toHaveClass(/selected/);

    // Verify badge has default styling
    await expect(badge).not.toHaveClass(/badge-active/);
  });
});
